 @Test public void chosenNasFolderThenAddPreparesTorrentWithoutStarting()throws Exception{try(FakeNas n=new FakeNas()){f.setup(n,List.of());f.instrumentation.waitForIdleSync();f.context.startActivity(new Intent().setComponent(new ComponentName(f.pkg+".test","hu.synostream.android.FixtureTorrentSender")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("kind","ok"));assertTrue(f.device.wait(Until.hasObject(By.text("Example.torrent")),10000));f.text("NAS-mappa kiválasztása");assertTrue(f.device.wait(Until.hasObject(By.text("NAS-megosztások")),10000));f.text("Movies");assertTrue(f.device.wait(Until.hasObject(By.text("/Movies")),10000));f.device.findObject(By.res("android:id/button1")).click();f.text("Hozzáadás");assertTrue(f.device.wait(Until.hasObject(By.text("release.nfo")),15000));assertTrue(n.torrentRouteValid);assertEquals("Movies",n.torrentDestination);assertEquals(1,n.torrentUploads);assertEquals(1,n.prepares);assertEquals(0,n.starts);assertTrue(f.device.findObject(By.text("release.nfo")).isChecked());assertFalse(f.device.findObject(By.text("Sample/clip.mkv")).isChecked());}}
